INSERT IGNORE INTO pages (`slug`, `locale`, `title`, `meta_description`, `is_published`, `content`) VALUES ('about','el','Σχετικά με το Lexicon','Τι είναι το Lexicon, ποιοι το δημιουργούν και τι πιστεύουμε για τη συγγραφή στο διαδίκτυο.',1,'<p>&Tau;&omicron; Lexicon &xi;&epsilon;&kappa;ί&nu;&eta;&sigma;&epsilon; &alpha;&pi;ό &mu;&iota;&alpha; &alpha;&pi;&lambda;ή &pi;&alpha;&rho;&alpha;&tau;ή&rho;&eta;&sigma;&eta;. &Eta; &delta;&eta;&mu;&omicron;&sigma;ί&epsilon;&upsilon;&sigma;&eta; &sigma;&tau;&omicron; &delta;&iota;&alpha;&delta;ί&kappa;&tau;&upsilon;&omicron; &epsilon;ί&chi;&epsilon; &gamma;ί&nu;&epsilon;&iota; &pi;&epsilon;&rho;ί&pi;&lambda;&omicron;&kappa;&eta;, &gamma;&epsilon;&mu;ά&tau;&eta; &pi;&rho;ό&sigma;&theta;&epsilon;&tau;&alpha;, &pi;ί&nu;&alpha;&kappa;&epsilon;&sigmaf; &epsilon;&lambda;έ&gamma;&chi;&omicron;&upsilon; &mu;έ&sigma;&alpha; &sigma;&epsilon; ά&lambda;&lambda;&omicron;&upsilon;&sigmaf; &pi;ί&nu;&alpha;&kappa;&epsilon;&sigmaf; &kappa;&alpha;&iota; &rho;&upsilon;&theta;&mu;ί&sigma;&epsilon;&iota;&sigmaf; &pi;&omicron;&upsilon; &kappa;&alpha;&nu;&epsilon;ί&sigmaf; &delta;&epsilon;&nu; &zeta;ή&tau;&eta;&sigma;&epsilon;. &Theta;έ&lambda;&alpha;&mu;&epsilon; έ&nu;&alpha;&nu; &chi;ώ&rho;&omicron; ό&pi;&omicron;&upsilon; &alpha;&pi;&lambda;ώ&sigmaf; &epsilon;&gamma;&gamma;&rho;ά&phi;&epsilon;&sigma;&alpha;&iota;, &delta;ί&nu;&epsilon;&iota;&sigmaf; ό&nu;&omicron;&mu;&alpha; &sigma;&tau;&omicron; blog &sigma;&omicron;&upsilon; &kappa;&alpha;&iota; &alpha;&rho;&chi;ί&zeta;&epsilon;&iota;&sigmaf; &nu;&alpha; &gamma;&rho;ά&phi;&epsilon;&iota;&sigmaf;. &Tau;ί&pi;&omicron;&tau;&alpha; &pi;&epsilon;&rho;&iota;&sigma;&sigma;ό&tau;&epsilon;&rho;&omicron;.</p>\r\n<p>&Sigma;ή&mu;&epsilon;&rho;&alpha; &tau;&omicron; Lexicon &epsilon;ί&nu;&alpha;&iota; έ&nu;&alpha; &sigma;&pi;ί&tau;&iota; &gamma;&iota;&alpha; &pi;&rho;&omicron;&sigma;&omega;&pi;&iota;&kappa;ά blogs, &omicron;&mu;&alpha;&delta;&iota;&kappa;έ&sigmaf; &delta;&eta;&mu;&omicron;&sigma;&iota;&epsilon;ύ&sigma;&epsilon;&iota;&sigmaf; &kappa;&alpha;&iota; &omicron;&tau;&iota;&delta;ή&pi;&omicron;&tau;&epsilon; &epsilon;&nu;&delta;&iota;ά&mu;&epsilon;&sigma;&alpha;. &Mu;&pi;&omicron;&rho;&epsilon;ί&sigmaf; &nu;&alpha; &gamma;&rho;ά&phi;&epsilon;&iota;&sigmaf; &mu;ό&nu;&omicron;&sigmaf; &sigma;&omicron;&upsilon; ή &nu;&alpha; &pi;&rho;&omicron;&sigma;&kappa;&alpha;&lambda;έ&sigma;&epsilon;&iota;&sigmaf; ά&lambda;&lambda;&omicron;&upsilon;&sigmaf; &alpha;&nu;&theta;&rho;ώ&pi;&omicron;&upsilon;&sigmaf; &nu;&alpha; &gamma;&rho;ά&psi;&omicron;&upsilon;&nu; &mu;&alpha;&zeta;ί &sigma;&omicron;&upsilon;. &Kappa;ά&theta;&epsilon; blog έ&chi;&epsilon;&iota; &tau;&eta; &delta;&iota;&kappa;ή &tau;&omicron;&upsilon; &alpha;&rho;&chi;&iota;&kappa;ή &sigma;&epsilon;&lambda;ί&delta;&alpha;, &kappa;&alpha;&tau;&eta;&gamma;&omicron;&rho;ί&epsilon;&sigmaf; &kappa;&alpha;&iota; &sigma;&chi;ό&lambda;&iota;&alpha;, &kappa;&alpha;&iota; &kappa;ά&theta;&epsilon; &sigma;&upsilon;&gamma;&gamma;&rho;&alpha;&phi;έ&alpha;&sigmaf; &delta;&iota;&alpha;&tau;&eta;&rho;&epsilon;ί &pi;&lambda;ή&rho;&eta; &iota;&delta;&iota;&omicron;&kappa;&tau;&eta;&sigma;ί&alpha; &tau;&omega;&nu; &kappa;&epsilon;&iota;&mu;έ&nu;&omega;&nu; &tau;&omicron;&upsilon;.</p>\r\n<h2>&Tau;&iota; &pi;&iota;&sigma;&tau;&epsilon;ύ&omicron;&upsilon;&mu;&epsilon;</h2>\r\n<ul>\r\n<li><strong>&Tau;&omicron; &pi;&epsilon;&rho;&iota;&epsilon;&chi;ό&mu;&epsilon;&nu;ό &sigma;&omicron;&upsilon; &epsilon;ί&nu;&alpha;&iota; &delta;&iota;&kappa;ό &sigma;&omicron;&upsilon;.</strong> &Mu;&pi;&omicron;&rho;&epsilon;ί&sigmaf; &nu;&alpha; &epsilon;&xi;ά&gamma;&epsilon;&iota;&sigmaf; ό,&tau;&iota; έ&chi;&epsilon;&iota;&sigmaf; &gamma;&rho;ά&psi;&epsilon;&iota; &omicron;&pi;&omicron;&iota;&alpha;&delta;ή&pi;&omicron;&tau;&epsilon; &sigma;&tau;&iota;&gamma;&mu;ή. &Alpha;&nu; &alpha;&pi;&omicron;&phi;&alpha;&sigma;ί&sigma;&epsilon;&iota;&sigmaf; &nu;&alpha; &phi;ύ&gamma;&epsilon;&iota;&sigmaf;, &mu;&pi;&omicron;&rho;&epsilon;ί&sigmaf; &nu;&alpha; &delta;&iota;&alpha;&gamma;&rho;ά&psi;&epsilon;&iota;&sigmaf; &tau;&omicron;&nu; &lambda;&omicron;&gamma;&alpha;&rho;&iota;&alpha;&sigma;&mu;ό &sigma;&omicron;&upsilon; &kappa;&alpha;&iota; &nu;&alpha; &pi;ά&rho;&epsilon;&iota;&sigmaf; &tau;&alpha; &kappa;&epsilon;ί&mu;&epsilon;&nu;ά &sigma;&omicron;&upsilon; &mu;&alpha;&zeta;ί &sigma;&omicron;&upsilon;.</li>\r\n<li><strong>&Eta; &alpha;&nu;ά&gamma;&nu;&omega;&sigma;&eta; &pi;&rho;έ&pi;&epsilon;&iota; &nu;&alpha; &epsilon;ί&nu;&alpha;&iota; &epsilon;&upsilon;&chi;ά&rho;&iota;&sigma;&tau;&eta;.</strong> &Kappa;&alpha;&theta;&alpha;&rho;ή &tau;&upsilon;&pi;&omicron;&gamma;&rho;&alpha;&phi;ί&alpha;, &gamma;&rho;ή&gamma;&omicron;&rho;&epsilon;&sigmaf; &sigma;&epsilon;&lambda;ί&delta;&epsilon;&sigmaf; &kappa;&alpha;&iota; &chi;&omega;&rho;ί&sigmaf; &delta;&iota;&alpha;&phi;&eta;&mu;&iota;&sigma;&tau;&iota;&kappa;ή &alpha;&kappa;&alpha;&tau;&alpha;&sigma;&tau;&alpha;&sigma;ί&alpha;.</li>\r\n<li><strong>&Omicron;&iota; &mu;&iota;&kappa;&rho;έ&sigmaf; &omicron;&mu;ά&delta;&epsilon;&sigmaf; &gamma;&rho;ά&phi;&omicron;&upsilon;&nu; &kappa;&alpha;&lambda;ύ&tau;&epsilon;&rho;&alpha; &mu;&alpha;&zeta;ί.</strong> &Rho;ό&lambda;&omicron;&iota; &kappa;&alpha;&iota; &rho;&omicron;ή &sigma;&upsilon;&nu;&tau;&alpha;&kappa;&tau;&iota;&kappa;ή&sigmaf; &epsilon;&pi;&iota;&mu;έ&lambda;&epsilon;&iota;&alpha;&sigmaf; &epsilon;ί&nu;&alpha;&iota; &epsilon;&nu;&sigma;&omega;&mu;&alpha;&tau;&omega;&mu;έ&nu;&alpha;, ώ&sigma;&tau;&epsilon; έ&nu;&alpha; &delta;&epsilon;ύ&tau;&epsilon;&rho;&omicron; &zeta;&epsilon;&upsilon;&gamma;ά&rho;&iota; &mu;ά&tau;&iota;&alpha; &nu;&alpha; &epsilon;ί&nu;&alpha;&iota; &pi;ά&nu;&tau;&alpha; &epsilon;ύ&kappa;&omicron;&lambda;&omicron; &nu;&alpha; &pi;&rho;&omicron;&sigma;&tau;&epsilon;&theta;&epsilon;ί.</li>\r\n</ul>\r\n<p>&Tau;&omicron; <strong>Lexicon</strong> &epsilon;ί&nu;&alpha;&iota; &nu;έ&omicron; &kappa;&alpha;&iota; &epsilon;&xi;&epsilon;&lambda;ί&sigma;&sigma;&epsilon;&tau;&alpha;&iota;. &Alpha;&nu; έ&chi;&epsilon;&iota;&sigmaf; &mu;&iota;&alpha; &iota;&delta;έ&alpha; &pi;&omicron;&upsilon; &theta;&alpha; &tau;&omicron; έ&kappa;&alpha;&nu;&epsilon; &kappa;&alpha;&lambda;ύ&tau;&epsilon;&rho;&omicron;, &theta;έ&lambda;&omicron;&upsilon;&mu;&epsilon; &pi;&rho;&alpha;&gamma;&mu;&alpha;&tau;&iota;&kappa;ά &nu;&alpha; &tau;&eta;&nu; &alpha;&kappa;&omicron;ύ&sigma;&omicron;&upsilon;&mu;&epsilon;. &Pi;&epsilon;&sigmaf; έ&nu;&alpha; &gamma;&epsilon;&iota;&alpha; &mu;έ&sigma;&omega; &tau;&eta;&sigmaf; <a href=\"contact\">&sigma;&epsilon;&lambda;ί&delta;&alpha;&sigmaf; &epsilon;&pi;&iota;&kappa;&omicron;&iota;&nu;&omega;&nu;ί&alpha;&sigmaf;</a>.</p>');
INSERT IGNORE INTO pages (`slug`, `locale`, `title`, `meta_description`, `is_published`, `content`) VALUES ('about','en','About Lexicon','What Lexicon is, who builds it, and what we believe about writing on the web.',1,'<p>Lexicon started with a simple observation. Publishing on the web had become complicated, full of plugins, dashboards inside dashboards and settings nobody asked for. We wanted a place where you sign up, name your blog and start writing. Nothing more.</p>\n<p>Today Lexicon is a home for personal blogs, team publications and everything in between. You can write alone or invite other people to write with you. Every blog gets its own home page, categories and comments, and every writer keeps full ownership of their words.</p>\n<h2>What we believe</h2>\n<ul>\n<li><strong>Your content is yours.</strong> You can export everything you have written at any time. If you decide to leave, you can delete your account and take your words with you.</li>\n<li><strong>Reading should be pleasant.</strong> Clean typography, fast pages and no advertising clutter.</li>\n<li><strong>Small teams write better together.</strong> Roles and an editorial review workflow are built in, so a second pair of eyes is always easy to add.</li>\n</ul>\n<p>Lexicon is young and growing. If you have an idea that would make it better, we genuinely want to hear it. Say hello through the <a href=\"/contact\">contact page</a>.</p>');
INSERT IGNORE INTO pages (`slug`, `locale`, `title`, `meta_description`, `is_published`, `content`) VALUES ('blog-with-your-team','en','Blog with your team','Invite co-writers, assign roles and review posts before they go live.',1,'<p>Some of the best blogs are written by more than one person. Lexicon has collaboration built in, so a team blog works the same way a personal one does, just with more people.</p>\r\n<h2>Invite people</h2>\r\n<p>From your blog\'s team page, send an invitation to anyone by email. They get a link, accept it, and appear in your team list. You can cancel pending invitations at any time.</p>\r\n<h2>Give everyone the right role</h2>\r\n<ul>\r\n<li><strong>Authors</strong> write and publish their own posts.</li>\r\n<li><strong>Contributors</strong> write drafts that someone else publishes.</li>\r\n<li><strong>Editors</strong> manage all the posts on the blog.</li>\r\n<li><strong>Reviewers</strong> read pending posts and approve them or request changes.</li>\r\n</ul>\r\n<h2>Turn on the review workflow</h2>\r\n<p>With the workflow enabled, a post goes through review before it can be published. The writer requests a review, a reviewer approves it or asks for changes, and everyone can see where each post stands. Nothing sloppy goes live by accident.</p>\r\n<h2>Moderate comments together</h2>\r\n<p>Comment moderation is shared with your editors, so questions from readers get answered even when you are away.</p>\r\n<p>Start small. Invite one person, write one post together, and grow from there.</p>');
INSERT IGNORE INTO pages (`slug`, `locale`, `title`, `meta_description`, `is_published`, `content`) VALUES ('contact','el','Επικοινωνήστε μαζί μας','Ερωτήσεις, ιδέες ή προβλήματα; Στείλτε ένα μήνυμα στην ομάδα του Lexicon.',1,'<p>Έ&chi;&epsilon;&tau;&epsilon; &mu;&iota;&alpha; &epsilon;&rho;ώ&tau;&eta;&sigma;&eta;, &beta;&rho;ή&kappa;&alpha;&tau;&epsilon; &kappa;ά&pi;&omicron;&iota;&omicron; &pi;&rho;ό&beta;&lambda;&eta;&mu;&alpha; ή &alpha;&pi;&lambda;ώ&sigmaf; &theta;έ&lambda;&epsilon;&tau;&epsilon; &nu;&alpha; &mu;&omicron;&iota;&rho;&alpha;&sigma;&tau;&epsilon;ί&tau;&epsilon; &mu;&iota;&alpha; &iota;&delta;έ&alpha;; &Sigma;&tau;&epsilon;ί&lambda;&tau;&epsilon; &mu;&alpha;&sigmaf; έ&nu;&alpha; &mu;ή&nu;&upsilon;&mu;&alpha; &kappa;&alpha;&iota; έ&nu;&alpha;&sigmaf; &pi;&rho;&alpha;&gamma;&mu;&alpha;&tau;&iota;&kappa;ό&sigmaf; ά&nu;&theta;&rho;&omega;&pi;&omicron;&sigmaf; &theta;&alpha; &tau;&omicron; &delta;&iota;&alpha;&beta;ά&sigma;&epsilon;&iota;. &Sigma;&upsilon;&nu;ή&theta;&omega;&sigmaf; &alpha;&pi;&alpha;&nu;&tau;ά&mu;&epsilon; &mu;έ&sigma;&alpha; &sigma;&epsilon; &delta;ύ&omicron; &epsilon;&rho;&gamma;ά&sigma;&iota;&mu;&epsilon;&sigmaf; &eta;&mu;έ&rho;&epsilon;&sigmaf;.</p>');
INSERT IGNORE INTO pages (`slug`, `locale`, `title`, `meta_description`, `is_published`, `content`) VALUES ('contact','en','Contact us','Questions, ideas or problems? Send the Lexicon team a message.',1,'<p>Have a question, found a problem, or just want to share an idea? Send us a message and a real person will read it. We usually reply within two working days.</p>');
INSERT IGNORE INTO pages (`slug`, `locale`, `title`, `meta_description`, `is_published`, `content`) VALUES ('cookies','el','Πολιτική Cookies','Τα cookies που χρησιμοποιεί το Lexicon και ο ρόλος που έχει το καθένα.',1,'<p>Το Lexicon χρησιμοποιεί μόνο τα cookies που χρειάζεται για να λειτουργεί, και δύο ακόμη αν τα επιτρέψεις. Δεν χρησιμοποιούμε cookies διαφήμισης ή παρακολούθησης σε άλλους ιστότοπους.</p>\n<h2>Cookies που χρησιμοποιούμε</h2>\n<ul>\n<li><strong>Cookie συνεδρίας (PHPSESSID).</strong> Σε κρατά συνδεδεμένο/η και προστατεύει τις φόρμες από πλαστογράφηση. Απαραίτητο. Διαγράφεται όταν κλείσεις το πρόγραμμα περιήγησης.</li>\n<li><strong>Επιλογή για τα cookies (app_consent).</strong> Θυμάται τι επέλεξες στο μήνυμα των cookies ώστε να μη σε ρωτάμε σε κάθε σελίδα. Απαραίτητο. Διατηρείται για 180 ημέρες.</li>\n<li><strong>Γλώσσα (locale).</strong> Θυμάται τη γλώσσα σου ανάμεσα στις επισκέψεις. Ορίζεται μόνο αν επιτρέψεις τα cookies Προτιμήσεων. Διατηρείται για 1 χρόνο.</li>\n<li><strong>Αναγνωριστικό ανάλυσης (lx_vid).</strong> Ένα τυχαίο αναγνωριστικό, ώστε όταν επιστρέφεις σε ένα blog να μετράς ως ο ίδιος αναγνώστης. Ορίζεται όταν επιτρέψεις τα cookies Ανάλυσης σε blog που μετρά επισκέψεις. Διατηρείται για 13 μήνες.</li>\n</ul>\n<h2>Αλλαγή της επιλογής σου</h2>\n<p>Χρησιμοποίησε το κουμπί cookies στο κάτω μέρος οποιασδήποτε σελίδας για να αλλάξεις ή να ανακαλέσεις την επιλογή σου. Μπορείς επίσης να διαγράψεις τα cookies από τις ρυθμίσεις του προγράμματος περιήγησης. Αν μπλοκάρεις το cookie συνεδρίας, θα αποσυνδεθείς.</p>');
INSERT IGNORE INTO pages (`slug`, `locale`, `title`, `meta_description`, `is_published`, `content`) VALUES ('cookies','en','Cookie Policy','The cookies Lexicon sets and what each one does.',1,'<p>Lexicon only uses the cookies it needs to work, plus two more if you allow them. We do not use advertising or cross-site tracking cookies.</p>\n<h2>Cookies we set</h2>\n<ul>\n<li><strong>Session cookie (PHPSESSID).</strong> Keeps you signed in and protects forms from forgery. Necessary. Deleted when you close your browser.</li>\n<li><strong>Cookie choice (app_consent).</strong> Remembers what you chose in the cookie banner so we do not ask on every page. Necessary. Kept for 180 days.</li>\n<li><strong>Language (locale).</strong> Remembers your language between visits. Set only if you allow Preferences cookies. Kept for 1 year.</li>\n<li><strong>Analytics id (lx_vid).</strong> A random id, so that coming back to a blog counts as the same reader. Set when you allow Analytics cookies on a blog that counts visits. Kept for 13 months.</li>\n</ul>\n<h2>Changing your choice</h2>\n<p>Use the cookie button at the bottom of any page to change or withdraw your choice. You can also delete cookies in your browser settings. Blocking the session cookie will sign you out.</p>');
INSERT IGNORE INTO pages (`slug`, `locale`, `title`, `meta_description`, `is_published`, `content`) VALUES ('privacy','el','Πολιτική Απορρήτου','Πώς το Lexicon συλλέγει, χρησιμοποιεί και προστατεύει τα προσωπικά σου δεδομένα.',1,'<p>Αυτή η πολιτική εξηγεί ποια προσωπικά δεδομένα συλλέγει το Lexicon, γιατί, πόσο καιρό τα κρατάμε και τι μπορείς να κάνεις γι’ αυτά. Την κρατάμε σύντομη επίτηδες, γιατί μια πολιτική απορρήτου που διαβάζεται πραγματικά αξίζει περισσότερο από δέκα σελίδες νομικών κειμένων.</p>\n<h2>Ποιος είναι υπεύθυνος</h2>\n<p>Το Lexicon λειτουργεί από [όνομα προσώπου ή εταιρείας, ταχυδρομική διεύθυνση]. Σύμφωνα με τον ΓΚΠΔ, αυτό μας κάνει υπεύθυνους επεξεργασίας των δεδομένων σου. Μπορείς να επικοινωνήσεις μαζί μας για οτιδήποτε αφορά αυτή την πολιτική μέσω της <a href=\"/el/contact\">σελίδας επαφών</a> ή στο [email για θέματα απορρήτου].</p>\n<h2>Τι συλλέγουμε και γιατί</h2>\n<ul>\n<li><strong>Στοιχεία λογαριασμού.</strong> Το όνομα, την ετικέτα, τη διεύθυνση email και τον κωδικό σου, καθώς και πότε επιβεβαίωσες ότι είσαι 16 ετών ή μεγαλύτερος/η. Τα χρειαζόμαστε για να έχεις λογαριασμό. Οι κωδικοί αποθηκεύονται σε μορφή hash και δεν μπορούμε ποτέ να τους διαβάσουμε.</li>\n<li><strong>Προφίλ.</strong> Ό,τι προσθέτεις στο προφίλ σου: βιογραφικό, επάγγελμα, τοποθεσία, φωτογραφία και συνδέσμους κοινωνικών δικτύων. Εσύ αποφασίζεις τι θα προσθέσεις και αν το προφίλ σου θα είναι δημόσιο.</li>\n<li><strong>Περιεχόμενο που δημοσιεύεις.</strong> Άρθρα, σχόλια, περιγραφές blog και εικόνες που ανεβάζεις. Το δημοσιευμένο περιεχόμενο είναι δημόσιο από τη φύση του.</li>\n<li><strong>Δραστηριότητα.</strong> Ψήφοι, σελιδοδείκτες, συνδρομές σε blog, αναφορές και οι ειδοποιήσεις που σου στέλνουμε, ώστε να λειτουργούν αυτές οι λειτουργίες για σένα.</li>\n<li><strong>Δεδομένα ασφαλείας.</strong> Διευθύνσεις IP και καταγραφή σημαντικών ενεργειών στον λογαριασμό, όπως αλλαγές κωδικού και διαγραφές. Τα κρατάμε για να προστατεύουμε την υπηρεσία και τον λογαριασμό σου, κάτι που αποτελεί έννομο συμφέρον μας.</li>\n<li><strong>Επισκέψεις σε blog.</strong> Στα blog όπου ο ιδιοκτήτης έχει ενεργοποιήσει τη μέτρηση επισκέψεων, μετράμε κάθε σελίδα που ανοίγεις: τη σελίδα, το όνομα του ιστότοπου από τον οποίο ήρθες, τις ετικέτες καμπάνιας του συνδέσμου, τον τύπο της συσκευής, του προγράμματος περιήγησης και του λειτουργικού συστήματος, τη χώρα σου, καθώς και πόσο διάβασες και πόσο κάτω κύλησες. Η διεύθυνση IP και τα στοιχεία του προγράμματος περιήγησης χρησιμοποιούνται τη στιγμή της επίσκεψης, για να ξεχωρίζουμε τους επισκέπτες μέσα στην ημέρα και για να βρούμε τη χώρα σου στον δικό μας διακομιστή. Όταν είσαι συνδεδεμένος/η, οι επισκέψεις συνδέονται με τον λογαριασμό σου μέσω ενός κρυπτογραφημένου αναγνωριστικού. Όταν επιτρέπεις τα cookies ανάλυσης, συνδέονται με ένα τυχαίο αναγνωριστικό σε cookie. Για να εξαιρεθείς, ενεργοποίησε το Global Privacy Control ή το Do Not Track στο πρόγραμμα περιήγησής σου. Μετράμε τις επισκέψεις γιατί οι συγγραφείς χρειάζεται να ξέρουν αν διαβάζονται, κάτι που αποτελεί έννομο συμφέρον μας. Οι συγγραφείς βλέπουν μόνο σύνολα.</li>\n<li><strong>Cookies.</strong> Ένα cookie συνεδρίας, την επιλογή σου για τα cookies και, μόνο αν τα επιτρέψεις, τη γλώσσα σου και ένα αναγνωριστικό ανάλυσης. Δες την <a href=\"/el/cookies\">πολιτική cookies</a>.</li>\n</ul>\n<p>Δεν πουλάμε τα δεδομένα σου, δεν προβάλλουμε διαφημίσεις, δεν σε παρακολουθούμε σε άλλους ιστότοπους και δεν λαμβάνουμε αυτοματοποιημένες αποφάσεις για σένα.</p>\n<h2>Ποιος άλλος τα χειρίζεται</h2>\n<p>Ο πάροχος φιλοξενίας αποθηκεύει τον ιστότοπο και τη βάση δεδομένων του, και ο πάροχος email παραδίδει τα μηνύματα που σου στέλνουμε. Επεξεργάζονται δεδομένα μόνο σύμφωνα με τις οδηγίες μας. [Αναφέρετε τους παρόχους φιλοξενίας και email και πού βρίσκονται οι διακομιστές τους. Αν δεδομένα φεύγουν από την ΕΕ, αναφέρετε την εγγύηση που χρησιμοποιείται, για παράδειγμα τις τυποποιημένες συμβατικές ρήτρες της ΕΕ.]</p>\n<h2>Πόσο καιρό τα κρατάμε</h2>\n<ul>\n<li>Λογαριασμός, προφίλ και δραστηριότητα: μέχρι να διαγράψεις τον λογαριασμό σου.</li>\n<li>Αρχεία ασφαλείας, μαζί με τις διευθύνσεις IP: 12 μήνες.</li>\n<li>Αντίγραφα των email που σου στέλνουμε: 30 ημέρες.</li>\n<li>Μεμονωμένες επισκέψεις σε blog: 30 ημέρες. Τα ημερήσια σύνολα που προκύπτουν από αυτές είναι ανώνυμα και διατηρούνται.</li>\n<li>Σύνδεσμοι επαναφοράς κωδικού και αλλαγής email: μέχρι να λήξουν.</li>\n<li>Συνδρομές σε blog που δεν επιβεβαιώθηκαν ποτέ: 7 ημέρες.</li>\n<li>Αντίγραφα ασφαλείας: [αριθμός] ημέρες, μετά αντικαθίστανται. Ένας διαγραμμένος λογαριασμός δεν επαναφέρεται ποτέ από αντίγραφο ασφαλείας.</li>\n</ul>\n<h2>Τα δικαιώματά σου</h2>\n<ul>\n<li><strong>Πάρε αντίγραφο.</strong> Κατέβασε όλα όσα κρατάμε για σένα από τις προτιμήσεις του λογαριασμού σου, στην ενότητα «Τα δεδομένα σας».</li>\n<li><strong>Διόρθωσέ τα.</strong> Άλλαξε τα στοιχεία σου οποιαδήποτε στιγμή από τις ρυθμίσεις του λογαριασμού.</li>\n<li><strong>Διάγραψέ τα.</strong> Διάγραψε τον λογαριασμό σου από τις προτιμήσεις του λογαριασμού. Ο λογαριασμός και τα προσωπικά σου δεδομένα διαγράφονται αμέσως, και εσύ επιλέγεις αν θα διαγραφούν και οι αναρτήσεις και τα σχόλιά σου ή αν θα μείνουν χωρίς το όνομά σου.</li>\n<li><strong>Αντιτάξου ή περιόρισε.</strong> Ζήτησέ μας μέσω της σελίδας επαφών να σταματήσουμε ή να περιορίσουμε μια χρήση των δεδομένων σου.</li>\n<li><strong>Ανακάλεσε τη συγκατάθεση.</strong> Άλλαξε την επιλογή σου για τα cookies οποιαδήποτε στιγμή με το κουμπί cookies στο κάτω μέρος κάθε σελίδας.</li>\n<li><strong>Υπόβαλε καταγγελία.</strong> Μπορείς να απευθυνθείς στην αρχή προστασίας δεδομένων της χώρας σου. Στην Ελλάδα είναι η Αρχή Προστασίας Δεδομένων Προσωπικού Χαρακτήρα, <a href=\"https://www.dpa.gr\">www.dpa.gr</a>.</li>\n</ul>\n<p>Απαντάμε στα αιτήματα μέσα σε έναν μήνα.</p>\n<h2>Ηλικία</h2>\n<p>Πρέπει να είσαι 16 ετών ή μεγαλύτερος/η για να δημιουργήσεις λογαριασμό.</p>\n<h2>Αλλαγές</h2>\n<p>Αν αλλάξουμε ουσιαστικά αυτή την πολιτική, θα το ανακοινώσουμε στον ιστότοπο πριν ισχύσει η αλλαγή.</p>');
INSERT IGNORE INTO pages (`slug`, `locale`, `title`, `meta_description`, `is_published`, `content`) VALUES ('privacy','en','Privacy Policy','How Lexicon collects, uses and protects your personal data.',1,'<p>This policy explains what personal data Lexicon collects, why, how long we keep it, and what you can do about it. We keep it short on purpose, because a privacy policy you actually read is worth more than ten pages of boilerplate.</p>\n<h2>Who is responsible</h2>\n<p>Lexicon is run by [name of the person or company, postal address]. Under the GDPR that makes us the controller of your data. You can reach us about anything in this policy through the <a href=\"/en/contact\">contact page</a> or at [privacy email address].</p>\n<h2>What we collect and why</h2>\n<ul>\n<li><strong>Account information.</strong> Your name, tag, email address and password, and when you confirmed you are 16 or older. We need these to give you an account. Passwords are stored hashed and we can never read them.</li>\n<li><strong>Profile.</strong> Whatever you add to your profile: bio, occupation, location, photo and social links. You decide what to add and whether your profile is public.</li>\n<li><strong>Content you publish.</strong> Posts, comments, blog descriptions and images you upload. Published content is public by definition.</li>\n<li><strong>Activity.</strong> Votes, bookmarks, blog subscriptions, reports and the notifications we send you, so these features work for you.</li>\n<li><strong>Security data.</strong> IP addresses and a record of important account actions such as password changes and deletions. We keep these to protect the service and your account, which is our legitimate interest.</li>\n<li><strong>Visits to blogs.</strong> On blogs whose owner has turned visit counting on, each page you open is counted: the page, the name of the site you came from, campaign tags in the link, your type of device, browser and operating system, your country, and how long you read and how far you scrolled. Your IP address and browser details are used at the time of the visit to tell visitors apart for the day and to look up your country on our own server. When you are signed in, visits are linked to your account through a scrambled id. When you allow analytics cookies, they are linked to a random id in a cookie. To opt out, turn on Global Privacy Control or Do Not Track in your browser. We count visits because blog authors need to know whether they are being read, which is our legitimate interest. Authors see only totals.</li>\n<li><strong>Cookies.</strong> A session cookie, your cookie choice and, only if you allow them, your language and an analytics id. See the <a href=\"/en/cookies\">cookie policy</a>.</li>\n</ul>\n<p>We do not sell your data, show advertising, follow you across other sites, or make automated decisions about you.</p>\n<h2>Who else handles it</h2>\n<p>Our hosting provider stores the site and its database, and our email provider delivers the messages we send you. They process data only on our instructions. [Name the hosting and email providers and where their servers are. If data leaves the EU, name the safeguard used, for example the EU standard contractual clauses.]</p>\n<h2>How long we keep it</h2>\n<ul>\n<li>Your account, profile and activity: until you delete your account.</li>\n<li>Security logs, including IP addresses: 12 months.</li>\n<li>Copies of emails we send you: 30 days.</li>\n<li>Individual visits to blogs: 30 days. The daily totals made from them are anonymous and kept.</li>\n<li>Password reset and email change links: until they expire.</li>\n<li>Blog subscriptions that were never confirmed: 7 days.</li>\n<li>Backups: [number] days, after which they are overwritten. A deleted account is never restored from a backup.</li>\n</ul>\n<h2>Your rights</h2>\n<ul>\n<li><strong>Get a copy.</strong> Download everything we hold about you from your account preferences, under Your data.</li>\n<li><strong>Correct it.</strong> Change your details at any time in your account settings.</li>\n<li><strong>Delete it.</strong> Delete your account from your account preferences. Your account and personal data are deleted straight away, and you choose whether your posts and comments are deleted too or kept without your name.</li>\n<li><strong>Object or restrict.</strong> Ask us through the contact page to stop or limit a use of your data.</li>\n<li><strong>Withdraw consent.</strong> Change your cookie choice at any time with the cookie button at the bottom of every page.</li>\n<li><strong>Complain.</strong> You can complain to your national data protection authority. In Greece that is the Hellenic Data Protection Authority, <a href=\"https://www.dpa.gr\">www.dpa.gr</a>.</li>\n</ul>\n<p>We answer requests within one month.</p>\n<h2>Age</h2>\n<p>You must be 16 or older to create an account.</p>\n<h2>Changes</h2>\n<p>If we change this policy in a meaningful way, we will say so on the site before the change takes effect.</p>');
INSERT IGNORE INTO pages (`slug`, `locale`, `title`, `meta_description`, `is_published`, `content`) VALUES ('start-your-first-blog','ar','ابدأ أول مدونة لك خلال 10 دقائق','From new account to published post, the short version.',1,'<p>لا تحتاج إلى خطة أو مجال متخصص أو جدول محتوى لكي تبدأ مدونة. كل ما تحتاجه هو حساب وشيء تريد قوله. هذه هي العملية كاملة.</p>\r\n\r\n<h2>1. أنشئ حسابك</h2>\r\n<p>سجل باستخدام بريدك الإلكتروني، ثم قم بتأكيده وسجّل الدخول. هذا كل شيء. لا يوجد خادم تحتاج إلى ضبطه ولا أي شيء تحتاج إلى تثبيته.</p>\r\n\r\n<h2>2. اختر اسمًا لمدونتك</h2>\r\n<p>من لوحة التحكم الخاصة بك، أنشئ مدونة جديدة. اختر اسمًا يعجبك ووصفًا قصيرًا يخبر القرّاء بما يمكنهم توقعه. لا تفكر بالأمر كثيرًا، يمكنك تغييرهما لاحقًا.</p>\r\n\r\n<h2>3. اكتب أول منشور لك</h2>\r\n<p>افتح المحرر وابدأ بالكتابة. أضف صورة بارزة إذا كانت لديك، فهي تجعل منشورك يبدو أفضل بكثير في القوائم وعلى الصفحة الرئيسية لمدونتك. عندما تكون راضيًا عنه، اضغط على نشر.</p>\r\n\r\n<h2>4. شاركه</h2>\r\n<p>للمدونة عنوان خاص يمكنك مشاركته في أي مكان. كل منشور يحصل على رابط نظيف يعمل في الرسائل والبريد الإلكتروني وملفات التعريف على الشبكات الاجتماعية.</p>\r\n\r\n<p>هذا بالفعل كل ما في الأمر. أفضل وقت لنشر أول منشور لك هو قبل أن تشعر بأنك جاهز.</p>');
INSERT IGNORE INTO pages (`slug`, `locale`, `title`, `meta_description`, `is_published`, `content`) VALUES ('start-your-first-blog','el','Ξεκίνα το πρώτο σου blog σε 10 λεπτά','Ξεκίνα το blog σου σε λίγα λεπτά με απλή εγγραφή, ένα όνομα και το πρώτο σου άρθρο χωρίς περίπλοκες ρυθμίσεις.',1,'<p>&Delta;&epsilon;&nu; &chi;&rho;&epsilon;&iota;ά&zeta;&epsilon;&sigma;&alpha;&iota; &pi;&lambda;ά&nu;&omicron;, &epsilon;&xi;&epsilon;&iota;&delta;ί&kappa;&epsilon;&upsilon;&sigma;&eta; ή &eta;&mu;&epsilon;&rho;&omicron;&lambda;ό&gamma;&iota;&omicron; &pi;&epsilon;&rho;&iota;&epsilon;&chi;&omicron;&mu;έ&nu;&omicron;&upsilon; &gamma;&iota;&alpha; &nu;&alpha; &xi;&epsilon;&kappa;&iota;&nu;ή&sigma;&epsilon;&iota;&sigmaf; έ&nu;&alpha; <strong>blog</strong>. &Chi;&rho;&epsilon;&iota;ά&zeta;&epsilon;&sigma;&alpha;&iota; έ&nu;&alpha;&nu; &lambda;&omicron;&gamma;&alpha;&rho;&iota;&alpha;&sigma;&mu;ό &kappa;&alpha;&iota; &kappa;ά&tau;&iota; &nu;&alpha; &pi;&epsilon;&iota;&sigmaf;. &Alpha;&upsilon;&tau;ή &epsilon;ί&nu;&alpha;&iota; ό&lambda;&eta; &eta; &delta;&iota;&alpha;&delta;&iota;&kappa;&alpha;&sigma;ί&alpha;.</p>\r\n<h2>1. &Delta;&eta;&mu;&iota;&omicron;ύ&rho;&gamma;&eta;&sigma;&epsilon; &tau;&omicron;&nu; &lambda;&omicron;&gamma;&alpha;&rho;&iota;&alpha;&sigma;&mu;ό &sigma;&omicron;&upsilon;</h2>\r\n<p>&Kappa;ά&nu;&epsilon; &epsilon;&gamma;&gamma;&rho;&alpha;&phi;ή &mu;&epsilon; &tau;&omicron; email &sigma;&omicron;&upsilon;, &epsilon;&pi;&iota;&beta;&epsilon;&beta;&alpha;ί&omega;&sigma;έ &tau;&omicron; &kappa;&alpha;&iota; &sigma;&upsilon;&nu;&delta;έ&sigma;&omicron;&upsilon;. &Delta;&epsilon;&nu; &upsilon;&pi;ά&rho;&chi;&epsilon;&iota; &delta;&iota;&alpha;&kappa;&omicron;&mu;&iota;&sigma;&tau;ή&sigmaf; &pi;&omicron;&upsilon; &pi;&rho;έ&pi;&epsilon;&iota; &nu;&alpha; &rho;&upsilon;&theta;&mu;ί&sigma;&epsilon;&iota;&sigmaf; &kappa;&alpha;&iota; &delta;&epsilon;&nu; &chi;&rho;&epsilon;&iota;ά&zeta;&epsilon;&tau;&alpha;&iota; &nu;&alpha; &epsilon;&gamma;&kappa;&alpha;&tau;&alpha;&sigma;&tau;ή&sigma;&epsilon;&iota;&sigmaf; &tau;ί&pi;&omicron;&tau;&alpha;.</p>\r\n<h2>2. &Delta;ώ&sigma;&epsilon; ό&nu;&omicron;&mu;&alpha; &sigma;&tau;&omicron; blog &sigma;&omicron;&upsilon;</h2>\r\n<p>&Alpha;&pi;ό &tau;&omicron;&nu; &pi;ί&nu;&alpha;&kappa;&alpha; &epsilon;&lambda;έ&gamma;&chi;&omicron;&upsilon; &sigma;&omicron;&upsilon; &delta;&eta;&mu;&iota;&omicron;ύ&rho;&gamma;&eta;&sigma;&epsilon; έ&nu;&alpha; &nu;έ&omicron; <strong>blog</strong>. &Delta;&iota;ά&lambda;&epsilon;&xi;&epsilon; έ&nu;&alpha; ό&nu;&omicron;&mu;&alpha; &pi;&omicron;&upsilon; &sigma;&omicron;&upsilon; &alpha;&rho;έ&sigma;&epsilon;&iota; &kappa;&alpha;&iota; &mu;&iota;&alpha; &sigma;ύ&nu;&tau;&omicron;&mu;&eta; &pi;&epsilon;&rho;&iota;&gamma;&rho;&alpha;&phi;ή &pi;&omicron;&upsilon; &beta;&omicron;&eta;&theta;ά &tau;&omicron;&upsilon;&sigmaf; &alpha;&nu;&alpha;&gamma;&nu;ώ&sigma;&tau;&epsilon;&sigmaf; &nu;&alpha; &kappa;&alpha;&tau;&alpha;&lambda;ά&beta;&omicron;&upsilon;&nu; &tau;&iota; &theta;&alpha; &beta;&rho;&omicron;&upsilon;&nu;. &Mu;&eta;&nu; &tau;&omicron; &pi;&alpha;&rho;&alpha;&sigma;&kappa;έ&phi;&tau;&epsilon;&sigma;&alpha;&iota;. &Mu;&pi;&omicron;&rho;&epsilon;ί&sigmaf; &nu;&alpha; &tau;&alpha; &alpha;&lambda;&lambda;ά&xi;&epsilon;&iota;&sigmaf; &kappa;&alpha;&iota; &tau;&alpha; &delta;ύ&omicron; &alpha;&rho;&gamma;ό&tau;&epsilon;&rho;&alpha;.</p>\r\n<h2>3. &Gamma;&rho;ά&psi;&epsilon; &tau;&omicron; &pi;&rho;ώ&tau;&omicron; &sigma;&omicron;&upsilon; ά&rho;&theta;&rho;&omicron;</h2>\r\n<p>Ά&nu;&omicron;&iota;&xi;&epsilon; &tau;&omicron;&nu; <strong>editor</strong> &kappa;&alpha;&iota; &gamma;&rho;ά&psi;&epsilon;. &Alpha;&nu; έ&chi;&epsilon;&iota;&sigmaf; &mu;&iota;&alpha; &epsilon;&iota;&kappa;ό&nu;&alpha; &pi;&rho;&omicron;&beta;&omicron;&lambda;ή&sigmaf; &mu;&pi;&omicron;&rho;&epsilon;ί&sigmaf; &nu;&alpha; &tau;&eta;&nu; &pi;&rho;&omicron;&sigma;&theta;έ&sigma;&epsilon;&iota;&sigmaf; &gamma;&iota;&alpha; &nu;&alpha; &delta;&epsilon;ί&chi;&nu;&epsilon;&iota; &kappa;&alpha;&lambda;ύ&tau;&epsilon;&rho;&alpha; &tau;&omicron; ά&rho;&theta;&rho;&omicron; &sigma;&omicron;&upsilon; &sigma;&tau;&iota;&sigmaf; &lambda;ί&sigma;&tau;&epsilon;&sigmaf; &kappa;&alpha;&iota; &sigma;&tau;&eta;&nu; &alpha;&rho;&chi;&iota;&kappa;ή &sigma;&epsilon;&lambda;ί&delta;&alpha; &tau;&omicron;&upsilon; blog &sigma;&omicron;&upsilon;. Ό&tau;&alpha;&nu; &epsilon;ί&sigma;&alpha;&iota; &iota;&kappa;&alpha;&nu;&omicron;&pi;&omicron;&iota;&eta;&mu;έ&nu;&omicron;&sigmaf; &pi;ά&tau;&eta;&sigma;&epsilon; &delta;&eta;&mu;&omicron;&sigma;ί&epsilon;&upsilon;&sigma;&eta;.</p>\r\n<h2>4. &Mu;&omicron;&iota;&rho;ά&sigma;&omicron;&upsilon; &tau;&omicron;</h2>\r\n<p>&Tau;&omicron; blog &sigma;&omicron;&upsilon; έ&chi;&epsilon;&iota; &tau;&eta; &delta;&iota;&kappa;ή &tau;&omicron;&upsilon; &delta;&iota;&epsilon;ύ&theta;&upsilon;&nu;&sigma;&eta; &pi;&omicron;&upsilon; &mu;&pi;&omicron;&rho;&epsilon;ί&sigmaf; &nu;&alpha; &mu;&omicron;&iota;&rho;&alpha;&sigma;&tau;&epsilon;ί&sigmaf; ό&pi;&omicron;&upsilon; &theta;έ&lambda;&epsilon;&iota;&sigmaf;. &Kappa;ά&theta;&epsilon; ά&rho;&theta;&rho;&omicron; &alpha;&pi;&omicron;&kappa;&tau;ά έ&nu;&alpha;&nu; &kappa;&alpha;&theta;&alpha;&rho;ό &sigma;ύ&nu;&delta;&epsilon;&sigma;&mu;&omicron; &pi;&omicron;&upsilon; &lambda;&epsilon;&iota;&tau;&omicron;&upsilon;&rho;&gamma;&epsilon;ί &sigma;&epsilon; &mu;ή&nu;&upsilon;&mu;&alpha;, email ή &pi;&rho;&omicron;&phi;ί&lambda; &kappa;&omicron;&iota;&nu;&omega;&nu;&iota;&kappa;ώ&nu; &delta;&iota;&kappa;&tau;ύ&omega;&nu;.</p>\r\n<p>&Alpha;&upsilon;&tau;ό &epsilon;ί&nu;&alpha;&iota; &pi;&rho;&alpha;&gamma;&mu;&alpha;&tau;&iota;&kappa;ά ό&lambda;&omicron;. &Eta; &kappa;&alpha;&lambda;ύ&tau;&epsilon;&rho;&eta; &sigma;&tau;&iota;&gamma;&mu;ή &gamma;&iota;&alpha; &nu;&alpha; &delta;&eta;&mu;&omicron;&sigma;&iota;&epsilon;ύ&sigma;&epsilon;&iota;&sigmaf; &tau;&omicron; &pi;&rho;ώ&tau;&omicron; &sigma;&omicron;&upsilon; ά&rho;&theta;&rho;&omicron; &epsilon;ί&nu;&alpha;&iota; &pi;&rho;&iota;&nu; &nu;&iota;ώ&sigma;&epsilon;&iota;&sigmaf; έ&tau;&omicron;&iota;&mu;&omicron;&sigmaf;.</p>');
INSERT IGNORE INTO pages (`slug`, `locale`, `title`, `meta_description`, `is_published`, `content`) VALUES ('start-your-first-blog','en','Start your first blog in 10 minutes','From new account to published post, the short version.',1,'<p>You do not need a plan, a niche or a content calendar to start a blog. You need an account and something to say. Here is the whole process.</p>\r\n<h2>1. Create your account</h2>\r\n<p>Register with your email, confirm it and sign in. That is it, there is no server to configure and nothing to install.</p>\r\n<h2>2. Name your blog</h2>\r\n<p>From your dashboard, create a new blog. Pick a name you like and a short description that tells readers what to expect. Do not overthink it, you can change both later.</p>\r\n<h2>3. Write your first post</h2>\r\n<p>Open the editor and write. Add a featured image if you have one, it makes your post look much better in lists and on your blog\'s home page. When you are happy with it, hit publish.</p>\r\n<h2>4. Share it</h2>\r\n<p>Your blog has its own address you can share anywhere. Every post gets a clean link that works in a message, an email or a social profile.</p>\r\n<p>That is genuinely all there is to it. The best time to publish your first post is before you feel ready.</p>');
INSERT IGNORE INTO pages (`slug`, `locale`, `title`, `meta_description`, `is_published`, `content`) VALUES ('terms','el','Όροι Χρήσης','The rules for using Lexicon, written in plain language.',1,'<p>Αυτοί οι όροι περιγράφουν τη συμφωνία ανάμεσα σε εσένα και το Lexicon όταν χρησιμοποιείς την πλατφόρμα. Απλή γλώσσα, χωρίς παγίδες.</p>\n<h2>Ο λογαριασμός σου</h2>\n<p>Πρέπει να είσαι 16 ετών ή μεγαλύτερος/η για να δημιουργήσεις λογαριασμό. Είσαι υπεύθυνος/η για τον λογαριασμό σου και για να κρατάς τον κωδικό σου ιδιωτικό. Πρέπει να δώσεις έγκυρη διεύθυνση email ώστε να μπορούμε να επικοινωνήσουμε μαζί σου για τον λογαριασμό όταν χρειαστεί.</p>\n<h2>Το περιεχόμενό σου</h2>\n<p>Ό,τι δημοσιεύεις στο Lexicon παραμένει δικό σου. Δημοσιεύοντας, μας δίνεις άδεια να αποθηκεύουμε και να εμφανίζουμε το περιεχόμενό σου ώστε να λειτουργεί η πλατφόρμα. Η άδεια αυτή λήγει όταν διαγράψεις το περιεχόμενο. Όταν διαγράφεις τον λογαριασμό σου, επιλέγεις αν θα διαγραφούν και οι αναρτήσεις και τα σχόλιά σου ή αν θα μείνουν χωρίς το όνομά σου.</p>\n<h2>Αποδεκτή χρήση</h2>\n<p>Μη χρησιμοποιείς το Lexicon για να δημοσιεύεις περιεχόμενο που είναι παράνομο, που παρενοχλεί ανθρώπους, που παραβιάζει πνευματικά δικαιώματα άλλων ή που διαδίδει κακόβουλο λογισμικό ή ανεπιθύμητα μηνύματα. Μπορεί να αφαιρέσουμε περιεχόμενο ή να αναστείλουμε λογαριασμούς που παραβιάζουν αυτούς τους κανόνες.</p>\n<h2>Εποπτεία</h2>\n<p>Οι κάτοχοι των blog εποπτεύουν τα σχόλια στα δικά τους blog. Η ομάδα του Lexicon εποπτεύει τις σελίδες της πλατφόρμας, όπως την αρχική σελίδα και τη σελίδα εξερεύνησης, και χειρίζεται τις αναφορές για περιεχόμενο που παραβιάζει τους παραπάνω κανόνες.</p>\n<h2>Τα δεδομένα σου</h2>\n<p>Ο τρόπος που χειριζόμαστε τα προσωπικά δεδομένα εξηγείται στην <a href=\"/el/privacy\">πολιτική απορρήτου</a>.</p>\n<h2>Η υπηρεσία</h2>\n<p>Προσπαθούμε να κρατάμε το Lexicon γρήγορο και διαθέσιμο, αλλά το παρέχουμε ως έχει, χωρίς εγγυήσεις. Μπορεί να αλλάξουμε ή να καταργήσουμε λειτουργίες, και θα σε ενημερώνουμε εκ των προτέρων για σημαντικές αλλαγές όταν είναι εύλογα εφικτό.</p>\n<h2>Αλλαγές σε αυτούς τους όρους</h2>\n<p>Αν αλλάξουμε ουσιαστικά αυτούς τους όρους, θα το ανακοινώσουμε πριν ισχύσει η αλλαγή. Αν συνεχίσεις να χρησιμοποιείς το Lexicon μετά από αυτό, αποδέχεσαι τους ενημερωμένους όρους.</p>');
INSERT IGNORE INTO pages (`slug`, `locale`, `title`, `meta_description`, `is_published`, `content`) VALUES ('terms','en','Terms of Service','The rules for using Lexicon, written in plain language.',1,'<p>These terms describe the agreement between you and Lexicon when you use the platform. Plain language, no tricks.</p>\n<h2>Your account</h2>\n<p>You must be 16 or older to create an account. You are responsible for your account and for keeping your password private. You must provide a valid email address so we can reach you about your account when needed.</p>\n<h2>Your content</h2>\n<p>Everything you publish on Lexicon remains yours. By publishing, you give us permission to store and display your content so the platform can work. That permission ends when you delete the content. When you delete your account you choose whether your posts and comments are deleted too, or stay up without your name.</p>\n<h2>Acceptable use</h2>\n<p>Do not use Lexicon to publish content that is illegal, that harasses people, that infringes someone else\'s copyright, or that spreads malware or spam. We may remove content or suspend accounts that break these rules.</p>\n<h2>Moderation</h2>\n<p>Blog owners moderate the comments on their own blogs. The Lexicon team moderates platform surfaces such as the front page and the explore page, and handles reports about content that breaks the rules above.</p>\n<h2>Your data</h2>\n<p>How we handle personal data is explained in the <a href=\"/en/privacy\">privacy policy</a>.</p>\n<h2>The service</h2>\n<p>We work hard to keep Lexicon fast and available, but we provide it as is, without warranties. We may change or discontinue features, and we will tell you about important changes in advance when we reasonably can.</p>\n<h2>Changes to these terms</h2>\n<p>If we change these terms in a meaningful way, we will announce it before the change takes effect. Continuing to use Lexicon after that means you accept the updated terms.</p>');
INSERT IGNORE INTO pages (`slug`, `locale`, `title`, `meta_description`, `is_published`, `content`) VALUES ('write-posts-people-read','el','Γράψε άρθρα που ο κόσμος θέλει να διαβάζει','Πρακτικές συνήθειες γραφής που κρατούν τον αναγνώστη στη σελίδα.',1,'<p>&Omicron;&iota; &pi;&epsilon;&rho;&iota;&sigma;&sigma;ό&tau;&epsilon;&rho;&omicron;&iota; &alpha;&nu;&alpha;&gamma;&nu;ώ&sigma;&tau;&epsilon;&sigmaf; &epsilon;&gamma;&kappa;&alpha;&tau;&alpha;&lambda;&epsilon;ί&pi;&omicron;&upsilon;&nu; έ&nu;&alpha; ά&rho;&theta;&rho;&omicron; &mu;έ&sigma;&alpha; &sigma;&tau;&alpha; &pi;&rho;ώ&tau;&alpha; &delta;&epsilon;&upsilon;&tau;&epsilon;&rho;ό&lambda;&epsilon;&pi;&tau;&alpha;. &Omicron;&iota; &sigma;&upsilon;&nu;ή&theta;&epsilon;&iota;&epsilon;&sigmaf; &alpha;&upsilon;&tau;έ&sigmaf; &delta;&iota;&omicron;&rho;&theta;ώ&nu;&omicron;&upsilon;&nu; &tau;&omicron; &pi;&rho;ό&beta;&lambda;&eta;&mu;&alpha; &kappa;&alpha;&iota; &delta;&epsilon;&nu; &chi;&rho;&epsilon;&iota;ά&zeta;&epsilon;&tau;&alpha;&iota; &nu;&alpha; έ&chi;&epsilon;&iota;&sigmaf; &tau;&alpha;&lambda;έ&nu;&tau;&omicron;. &Alpha;&rho;&kappa;&epsilon;ί &lambda;ί&gamma;&eta; &phi;&rho;&omicron;&nu;&tau;ί&delta;&alpha;.</p>\r\n<h2>&Kappa;έ&rho;&delta;&iota;&sigma;&epsilon; &tau;&omicron; &kappa;&lambda;&iota;&kappa; &mu;&epsilon; έ&nu;&alpha;&nu; &tau;ί&tau;&lambda;&omicron; &pi;&omicron;&upsilon; &upsilon;&pi;ό&sigma;&chi;&epsilon;&tau;&alpha;&iota; &kappa;ά&tau;&iota;</h2>\r\n<p>&Pi;&epsilon;&sigmaf; &xi;&epsilon;&kappa;ά&theta;&alpha;&rho;&alpha; &tau;&iota; &theta;&alpha; &pi;ά&rho;&epsilon;&iota; &omicron; &alpha;&nu;&alpha;&gamma;&nu;ώ&sigma;&tau;&eta;&sigmaf;.<br>&laquo;&Mu;&epsilon;&rho;&iota;&kappa;έ&sigmaf; &sigma;&kappa;έ&psi;&epsilon;&iota;&sigmaf; &gamma;&iota;&alpha; &tau;&eta; &mu;&alpha;&gamma;&epsilon;&iota;&rho;&iota;&kappa;ή&raquo; &delta;&epsilon;&nu; &lambda;έ&epsilon;&iota; &pi;&omicron;&lambda;&lambda;ά.<br>&laquo;&Pi;έ&nu;&tau;&epsilon; &delta;&epsilon;ί&pi;&nu;&alpha; &pi;&omicron;&upsilon; &epsilon;&tau;&omicron;&iota;&mu;ά&zeta;&epsilon;&iota;&sigmaf; &pi;&iota;&omicron; &gamma;&rho;ή&gamma;&omicron;&rho;&alpha; &alpha;&pi;ό &tau;&omicron; delivery&raquo; &delta;ί&nu;&epsilon;&iota; &mu;&iota;&alpha; &upsilon;&pi;ό&sigma;&chi;&epsilon;&sigma;&eta; &kappa;&alpha;&iota; &kappa;ά&nu;&epsilon;&iota; &tau;&omicron;&nu; &alpha;&nu;&alpha;&gamma;&nu;ώ&sigma;&tau;&eta; &nu;&alpha; &theta;έ&lambda;&epsilon;&iota; &nu;&alpha; &mu;ά&theta;&epsilon;&iota; &pi;&epsilon;&rho;&iota;&sigma;&sigma;ό&tau;&epsilon;&rho;&alpha;.</p>\r\n<h2>&Kappa;&rho;ά&tau;&alpha; &tau;&iota;&sigmaf; &pi;&alpha;&rho;&alpha;&gamma;&rho;ά&phi;&omicron;&upsilon;&sigmaf; &mu;&iota;&kappa;&rho;έ&sigmaf;</h2>\r\n<p>&Omicron;&iota; &mu;&epsilon;&gamma;ά&lambda;&epsilon;&sigmaf; &epsilon;&nu;ό&tau;&eta;&tau;&epsilon;&sigmaf; &kappa;&omicron;&upsilon;&rho;ά&zeta;&omicron;&upsilon;&nu;.<br>&Tau;&rho;&epsilon;&iota;&sigmaf; &mu;&epsilon; &tau;έ&sigma;&sigma;&epsilon;&rho;&iota;&sigmaf; &pi;&rho;&omicron;&tau;ά&sigma;&epsilon;&iota;&sigmaf; &alpha;&rho;&kappa;&omicron;ύ&nu; &gamma;&iota;&alpha; &nu;&alpha; &alpha;&nu;&alpha;&pi;&nu;έ&epsilon;&iota; &tau;&omicron; &kappa;&epsilon;ί&mu;&epsilon;&nu;&omicron; &kappa;&alpha;&iota; &nu;&alpha; &phi;&alpha;ί&nu;&epsilon;&tau;&alpha;&iota; &pi;&iota;&omicron; &gamma;&rho;ή&gamma;&omicron;&rho;&omicron; &sigma;&tau;&eta;&nu; &alpha;&nu;ά&gamma;&nu;&omega;&sigma;&eta; &alpha;&pi;ό ό&sigma;&omicron; &epsilon;ί&nu;&alpha;&iota;.</p>\r\n<h2>&Mu;ί&alpha; &epsilon;&iota;&kappa;ό&nu;&alpha; &pi;&rho;&omicron;&beta;&omicron;&lambda;ή&sigmaf; &alpha;&rho;&kappa;&epsilon;ί</h2>\r\n<p>&Mu;&iota;&alpha; &kappa;&alpha;&lambda;ή &epsilon;&iota;&kappa;ό&nu;&alpha; &kappa;ά&nu;&epsilon;&iota; &tau;&omicron; ά&rho;&theta;&rho;&omicron; &nu;&alpha; &xi;&epsilon;&chi;&omega;&rho;ί&zeta;&epsilon;&iota; &sigma;&epsilon; &kappa;ά&theta;&epsilon; &lambda;ί&sigma;&tau;&alpha;.<br>&Delta;&iota;ά&lambda;&epsilon;&xi;&epsilon; &mu;ί&alpha; &pi;&omicron;&upsilon; &tau;&alpha;&iota;&rho;&iota;ά&zeta;&epsilon;&iota; &sigma;&tau;&omicron; ύ&phi;&omicron;&sigmaf; &kappa;&alpha;&iota; ά&phi;&eta;&sigma;&epsilon; &tau;&omicron; &kappa;&epsilon;ί&mu;&epsilon;&nu;&omicron; &nu;&alpha; &kappa;ά&nu;&epsilon;&iota; &tau;&eta; &delta;&omicron;&upsilon;&lambda;&epsilon;&iota;ά &tau;&omicron;&upsilon;.</p>\r\n<h2>&Omicron;&rho;&gamma;ά&nu;&omega;&sigma;&epsilon; &sigma;&omega;&sigma;&tau;ά &kappa;&alpha;&tau;&eta;&gamma;&omicron;&rho;ί&epsilon;&sigmaf; &kappa;&alpha;&iota; &epsilon;&tau;&iota;&kappa;έ&tau;&epsilon;&sigmaf;</h2>\r\n<p>&Omicron;&iota; &kappa;&alpha;&tau;&eta;&gamma;&omicron;&rho;ί&epsilon;&sigmaf; &epsilon;ί&nu;&alpha;&iota; &tau;&alpha; &mu;&epsilon;&gamma;ά&lambda;&alpha; &rho;ά&phi;&iota;&alpha; &tau;&omicron;&upsilon; blog &sigma;&omicron;&upsilon;.<br>&Omicron;&iota; &epsilon;&tau;&iota;&kappa;έ&tau;&epsilon;&sigmaf; &epsilon;ί&nu;&alpha;&iota; &omicron;&iota; &lambda;&epsilon;&pi;&tau;&omicron;&mu;έ&rho;&epsilon;&iota;&epsilon;&sigmaf; &pi;&omicron;&upsilon; &beta;&omicron;&eta;&theta;&omicron;ύ&nu; &tau;&omicron;&nu; &alpha;&nu;&alpha;&gamma;&nu;ώ&sigma;&tau;&eta; &nu;&alpha; &beta;&rho;&epsilon;&iota; ό,&tau;&iota; &tau;&omicron;&nu; &epsilon;&nu;&delta;&iota;&alpha;&phi;έ&rho;&epsilon;&iota;.<br>&Alpha;&nu; &kappa;ά&pi;&omicron;&iota;&omicron;&sigmaf; &alpha;&gamma;&alpha;&pi;ή&sigma;&epsilon;&iota; έ&nu;&alpha; ά&rho;&theta;&rho;&omicron; &gamma;&iota;&alpha; &pi;&epsilon;&zeta;&omicron;&pi;&omicron;&rho;ί&alpha;, &pi;&rho;έ&pi;&epsilon;&iota; &mu;&epsilon; έ&nu;&alpha; &kappa;&lambda;&iota;&kappa; &nu;&alpha; &beta;&rho;ί&sigma;&kappa;&epsilon;&iota; ό&lambda;&alpha; &tau;&alpha; &upsilon;&pi;ό&lambda;&omicron;&iota;&pi;&alpha;.</p>\r\n<h2>&Kappa;&lambda;&epsilon;ί&sigma;&epsilon; &mu;&epsilon; έ&nu;&alpha; &epsilon;&pi;ό&mu;&epsilon;&nu;&omicron; &beta;ή&mu;&alpha;</h2>\r\n<p>&Mu;&iota;&alpha; &epsilon;&rho;ώ&tau;&eta;&sigma;&eta;, &mu;&iota;&alpha; &pi;&rho;ό&tau;&alpha;&sigma;&eta;, έ&nu;&alpha;&sigmaf; &sigma;ύ&nu;&delta;&epsilon;&sigma;&mu;&omicron;&sigmaf; &gamma;&iota;&alpha; &sigma;&upsilon;&nu;έ&chi;&epsilon;&iota;&alpha;.<br>Ό&sigma;&omicron;&iota; &phi;&tau;ά&nu;&omicron;&upsilon;&nu; &sigma;&tau;&omicron; &tau;έ&lambda;&omicron;&sigmaf; &epsilon;ί&nu;&alpha;&iota; &omicron;&iota; &pi;&iota;&omicron; &alpha;&phi;&omicron;&sigma;&iota;&omega;&mu;έ&nu;&omicron;&iota; &alpha;&nu;&alpha;&gamma;&nu;ώ&sigma;&tau;&epsilon;&sigmaf; &sigma;&omicron;&upsilon;. &Delta;ώ&sigma;&epsilon; &tau;&omicron;&upsilon;&sigmaf; &kappa;ά&tau;&iota; &nu;&alpha; &kappa;ά&nu;&omicron;&upsilon;&nu; &mu;&epsilon;&tau;ά.</p>');
INSERT IGNORE INTO pages (`slug`, `locale`, `title`, `meta_description`, `is_published`, `content`) VALUES ('write-posts-people-read','en','Write posts people actually read','Practical writing habits that keep readers on the page.',1,'<p>Most posts lose their readers in the first ten seconds. These habits fix that, and none of them require talent, just a little care.</p>\r\n<h2>Earn the click with the title</h2>\r\n<p>Say what the reader gets, specifically. Compare \"Some thoughts on cooking\" with \"Five dinners you can cook in the time it takes to order delivery\". The second one makes a promise.</p>\r\n<h2>Keep paragraphs short</h2>\r\n<p>Long blocks of text look like work. Three or four sentences per paragraph gives the eye somewhere to rest and makes your post feel faster to read than it is.</p>\r\n<h2>Use one featured image</h2>\r\n<p>Posts with a featured image get noticed in every list they appear in. Choose one image that captures the mood of the post, and let the writing do the rest.</p>\r\n<h2>Organize with categories and tags</h2>\r\n<p>Categories are the big shelves of your blog, tags are the labels. A reader who liked one post about hiking should be one click away from all your other hiking posts.</p>\r\n<h2>End with something to do</h2>\r\n<p>A question, a recommendation, a link to a related post. Readers who reach the end are your most interested readers, give them a next step.</p>');
